/* =========================================================
   LIVE PREVIEW WIRING
========================================================= */
function wireLiveInputs() {
  const ids = [
    'institutionName','department','documentType','courseCode','courseName',
    'serialNo','submissionDate','reportTitle','studentName','studentRoll',
    'studentReg','studentExamRoll','studentBatch',
    'teacherNameManual','teacherDesigManual','teacherDeptManual'
  ];
  ids.forEach(id => {
    const el = $(id);
    el.addEventListener('input', () => { updatePreview(); validateField(el); });
    el.addEventListener('change', () => { updatePreview(); validateField(el); });
  });
}

function validateField(el) {
  const required = el.hasAttribute('required');
  if (!required) return;
  if (!el.value.trim()) el.classList.add('invalid');
  else el.classList.remove('invalid');
}

/* =========================================================
   UPDATE THE COVER PAGE PREVIEW
========================================================= */
function updatePreview() {
  const institution = $('institutionName').value.trim() || 'Your Institution Name';
  $('pInstitution').textContent = institution;

  const dept = $('department').value;
  $('pDepartment').textContent = `Department of ${dept}`;
  $('pTeacherInst').textContent = institution;

  $('pDocType').textContent = $('documentType').value.toUpperCase();

  $('pCourseName').textContent = $('courseName').value.trim() || '—';
  $('pCourseCode').textContent = $('courseCode').value.trim() || '—';

  const serial = $('serialNo').value.trim();
  const serialWrap = $('pSerialWrap');
  const docType = $('documentType').value;
  $('pSerialLabel').textContent = docType === 'Project' ? 'Project No' : 'Serial No';
  if (serial) { serialWrap.hidden = false; $('pSerialNo').textContent = serial; }
  else { serialWrap.hidden = true; }

  const title = $('reportTitle').value.trim();
  const titleWrap = $('pTitleWrap');
  if (title) { titleWrap.hidden = false; $('pTitle').textContent = title; }
  else { titleWrap.hidden = true; }

  $('pStudentName').textContent = $('studentName').value.trim() || '—';
  $('pStudentRoll').textContent = $('studentRoll').value.trim() || '—';
  $('pStudentReg').textContent = $('studentReg').value.trim() || '—';
  $('pStudentExamRoll').textContent = $('studentExamRoll').value.trim() || '—';
  $('pStudentBatch').textContent = $('studentBatch').value.trim() || '—';

  // teacher block
  const manual = $('manualTeacherEntry').checked;
  let tName = '—', tDesig = '—', tDept = '—';
  if (manual) {
    tName = $('teacherNameManual').value.trim() || '—';
    tDesig = $('teacherDesigManual').value.trim() || '—';
    tDept = $('teacherDeptManual').value.trim() || '—';
  } else if (selectedTeacher) {
    tName = selectedTeacher.name;
    tDesig = selectedTeacher.designation;
    tDept = selectedTeacher.department;
  }
  $('pTeacherName').textContent = tName;
  $('pTeacherDesig').textContent = tDesig;
  $('pTeacherDept').textContent = tDept;

  // date, formatted nicely
  const dateVal = $('submissionDate').value;
  $('pDate').textContent = dateVal ? formatDate(dateVal) : '—';

  // logo
  const logoImg = $('pLogo'), logoPh = $('pLogoPlaceholder');
  if (logoDataUrl) { logoImg.src = logoDataUrl; logoImg.hidden = false; logoPh.hidden = true; }
  else { logoImg.hidden = true; logoPh.hidden = false; }

  // watermark
  const wm = $('coverWatermark');
  const enabled = $('watermarkEnabled').checked;
  const opacity = Number($('watermarkOpacity').value) / 100;
  const src = watermarkDataUrl || logoDataUrl;
  if (enabled && src) {
    wm.style.backgroundImage = `url(${src})`;
    wm.style.opacity = opacity;
  } else {
    wm.style.backgroundImage = 'none';
  }

  autosave();
  updateIndexHeader();
}

function formatDate(isoStr) {
  const d = new Date(isoStr + 'T00:00:00');
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });
}

/* =========================================================
   UPLOAD BOXES (logo / watermark)
========================================================= */
function wireUploadBoxes() {
  setupUpload('logoUploadBox', 'logoUpload', 'logoPreviewImg', 'logoUploadHint', 'logoRemoveBtn', (dataUrl) => {
    logoDataUrl = dataUrl; updatePreview();
  });
  setupUpload('watermarkUploadBox', 'watermarkUpload', 'watermarkPreviewImg', 'watermarkUploadHint', 'watermarkRemoveBtn', (dataUrl) => {
    watermarkDataUrl = dataUrl; updatePreview();
  });

  $('logoResetDefault').addEventListener('click', () => { applyLogo(DEFAULT_LOGO, 'logo'); updatePreview(); });
  $('watermarkResetDefault').addEventListener('click', () => { applyLogo(DEFAULT_LOGO, 'watermark'); updatePreview(); });

  // A small "✕" on the thumb itself removes a custom upload and — per spec —
  // automatically falls back to the default MEC crest, same as the reset link.
  $('logoRemoveBtn').addEventListener('click', (e) => {
    e.stopPropagation(); applyLogo(DEFAULT_LOGO, 'logo'); updatePreview();
    setStatus('Logo removed — restored the MEC default.');
  });
  $('watermarkRemoveBtn').addEventListener('click', (e) => {
    e.stopPropagation(); applyLogo(DEFAULT_LOGO, 'watermark'); updatePreview();
    setStatus('Watermark removed — restored the MEC default.');
  });
}

/* Sets a logo/watermark from any URL (default asset or an uploaded data: URL)
   and keeps the little upload-box preview (and its remove button) in sync. */
function applyLogo(url, which) {
  const img = which === 'logo' ? $('logoPreviewImg') : $('watermarkPreviewImg');
  const hint = which === 'logo' ? $('logoUploadHint') : $('watermarkUploadHint');
  const removeBtn = which === 'logo' ? $('logoRemoveBtn') : $('watermarkRemoveBtn');
  img.src = url; img.hidden = false; hint.hidden = true;
  removeBtn.hidden = (url === DEFAULT_LOGO);
  if (which === 'logo') logoDataUrl = url; else watermarkDataUrl = url;
}

function setupUpload(boxId, inputId, imgId, hintId, removeBtnId, onLoaded) {
  const box = $(boxId), input = $(inputId), img = $(imgId), hint = $(hintId), removeBtn = $(removeBtnId);
  box.addEventListener('click', (e) => { if (e.target !== removeBtn) input.click(); });
  input.addEventListener('change', () => {
    const file = input.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      img.src = e.target.result; img.hidden = false; hint.hidden = true; removeBtn.hidden = false;
      onLoaded(e.target.result);
    };
    reader.readAsDataURL(file);
  });
}

/* =========================================================
   WATERMARK CONTROLS
========================================================= */
function wireWatermarkControls() {
  $('watermarkEnabled').addEventListener('change', updatePreview);
  $('watermarkOpacity').addEventListener('input', () => {
    $('opacityValue').textContent = `${$('watermarkOpacity').value}%`;
    updatePreview();
  });
}

/* =========================================================
   TEMPLATE SWITCHER — swaps #coverPage's data-template attribute;
   CSS alone re-flows the same bound content into a different layout.
========================================================= */
function wireTemplateSwitcher() {
  $('templateGrid').addEventListener('click', (e) => {
    const btn = e.target.closest('.tpl-swatch');
    if (!btn) return;
    setTemplate(btn.dataset.tpl);
    autosave();
  });
}
function setTemplate(tpl) {
  currentTemplate = tpl || 'classic';
  $('coverPage').dataset.template = currentTemplate;
  document.querySelectorAll('.tpl-swatch').forEach(el => {
    const isActive = el.dataset.tpl === currentTemplate;
    el.classList.toggle('active', isActive);
    el.setAttribute('aria-pressed', isActive ? 'true' : 'false');
  });
}

/* =========================================================
   STYLE / CUSTOMIZATION PANEL — accent colour, font pairing, title case,
   logo shape, border/frame, divider style, spacing density. All layer on
   top of #coverPage via data-* attributes + a handful of CSS variables,
   so no template's markup or JS needs to know about them.
========================================================= */
function hexToRgb(hex) {
  const clean = hex.replace('#', '');
  const full = clean.length === 3 ? clean.split('').map(c => c + c).join('') : clean;
  const num = parseInt(full, 16);
  return { r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255 };
}
function rgbToHex(r, g, b) {
  return '#' + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
}
/* percent > 0 lightens toward white, percent < 0 darkens toward black */
function shadeHex(hex, percent) {
  const { r, g, b } = hexToRgb(hex);
  const target = percent < 0 ? 0 : 255;
  const p = Math.min(Math.abs(percent), 100) / 100;
  return rgbToHex(r + (target - r) * p, g + (target - g) * p, b + (target - b) * p);
}

function applyStyleState() {
  const cover = $('coverPage');
  cover.dataset.font = styleState.font;
  cover.dataset.titlecase = styleState.titlecase;
  cover.dataset.logoshape = styleState.logoshape;
  cover.dataset.border = styleState.border;
  cover.dataset.divider = styleState.divider;
  cover.dataset.density = styleState.density;

  // Accent colour lives on :root (not just #coverPage) so the Index Page
  // preview — a separate printable sheet — picks up the same palette.
  const root = document.documentElement.style;
  root.setProperty('--cover-accent', styleState.accent);
  root.setProperty('--cover-accent-dark', shadeHex(styleState.accent, -22));
  root.setProperty('--cover-accent-tint', shadeHex(styleState.accent, 88));

  // sync chip/dot active states
  document.querySelectorAll('.chip-row[data-group]').forEach(row => {
    const group = row.dataset.group;
    row.querySelectorAll('.chip').forEach(chip => {
      chip.classList.toggle('active', chip.dataset.value === styleState[group]);
    });
  });
  document.querySelectorAll('.accent-dot').forEach(dot => {
    dot.classList.toggle('active', dot.dataset.value.toLowerCase() === styleState.accent.toLowerCase());
  });
  const isPreset = Array.from(document.querySelectorAll('.accent-dot')).some(d => d.dataset.value.toLowerCase() === styleState.accent.toLowerCase());
  $('accentCustomWrap').classList.toggle('active', !isPreset);
  $('accentCustom').value = styleState.accent;
}

function wireStyleControls() {
  // generic chip groups: font / title case / logo shape / border / divider / density
  document.querySelectorAll('.chip-row[data-group]').forEach(row => {
    row.addEventListener('click', (e) => {
      const btn = e.target.closest('.chip');
      if (!btn) return;
      styleState[row.dataset.group] = btn.dataset.value;
      applyStyleState();
      autosave();
    });
  });

  // accent preset dots
  $('accentRow').addEventListener('click', (e) => {
    const dot = e.target.closest('.accent-dot');
    if (!dot) return;
    styleState.accent = dot.dataset.value;
    applyStyleState();
    autosave();
  });

  // custom colour wheel
  $('accentCustom').addEventListener('input', (e) => {
    styleState.accent = e.target.value;
    applyStyleState();
  });
  $('accentCustom').addEventListener('change', autosave);

  $('styleReset').addEventListener('click', () => {
    styleState = { ...DEFAULT_STYLE };
    applyStyleState();
    autosave();
    setStatus('Style reset to defaults.');
  });

  applyStyleState();
}

/* =========================================================
   TEACHER SEARCH (Mode 1) + MANUAL (Mode 2)
========================================================= */
function wireTeacherSearch() {
  const input = $('teacherSearch');
  const list = $('teacherResults');
  const deptFilter = $('teacherDeptFilter');

  const runSearch = () => {
    const q = input.value.trim().toLowerCase();
    const dept = deptFilter.value;
    list.innerHTML = '';

    // Nothing typed and no department chosen — no need to show a list yet.
    if (!q && !dept) { list.hidden = true; return; }

    const matches = TEACHERS.filter(t =>
      (!q || t.name.toLowerCase().includes(q)) &&
      (!dept || t.department === dept)
    );

    if (matches.length === 0) {
      list.innerHTML = `<li class="combo-empty">No teacher matches these filters.</li>`;
      list.hidden = false;
      return;
    }
    matches.forEach(t => {
      const li = document.createElement('li');
      li.innerHTML = `<strong>${escapeHtml(t.name)}</strong><span>${escapeHtml(t.designation)} · ${escapeHtml(t.department)}</span>`;
      li.addEventListener('click', () => chooseTeacher(t));
      list.appendChild(li);
    });
    list.hidden = false;
  };

  input.addEventListener('input', runSearch);
  deptFilter.addEventListener('change', runSearch);
  input.addEventListener('focus', () => { if (deptFilter.value) runSearch(); });

  document.addEventListener('click', (e) => {
    if (!e.target.closest('.combo') && !e.target.closest('#teacherDeptFilter')) list.hidden = true;
  });

  $('teacherClear').addEventListener('click', () => {
    selectedTeacher = null;
    $('teacherChosen').hidden = true;
    $('teacherSearchWrap').hidden = false;
    $('teacherSearch').value = '';
    updatePreview();
  });
}

function chooseTeacher(t) {
  selectedTeacher = t;
  $('teacherSearchWrap').hidden = true;
  const chosen = $('teacherChosen');
  chosen.hidden = false;
  $('tcName').textContent = t.name;
  $('tcDesig').textContent = t.designation;
  $('tcDept').textContent = t.department;
  $('teacherResults').hidden = true;
  updatePreview();
}

function wireManualTeacherToggle() {
  const checkbox = $('manualTeacherEntry');
  checkbox.addEventListener('change', () => {
    const manual = checkbox.checked;
    $('teacherManualWrap').hidden = !manual;
    $('teacherSearchWrap').hidden = manual || !!selectedTeacher;
    $('teacherChosen').hidden = manual || !selectedTeacher;
    updatePreview();
  });
}

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

/* =========================================================
   COLLECT / APPLY FORM DATA
========================================================= */
function collectFormData() {
  return {
    template: currentTemplate,
    style: { ...styleState },
    institutionName: $('institutionName').value,
    department: $('department').value,
    documentType: $('documentType').value,
    courseCode: $('courseCode').value,
    courseName: $('courseName').value,
    serialNo: $('serialNo').value,
    submissionDate: $('submissionDate').value,
    reportTitle: $('reportTitle').value,
    studentName: $('studentName').value,
    studentRoll: $('studentRoll').value,
    studentReg: $('studentReg').value,
    studentExamRoll: $('studentExamRoll').value,
    studentBatch: $('studentBatch').value,
    manualTeacherEntry: $('manualTeacherEntry').checked,
    teacherNameManual: $('teacherNameManual').value,
    teacherDesigManual: $('teacherDesigManual').value,
    teacherDeptManual: $('teacherDeptManual').value,
    selectedTeacher,
    watermarkEnabled: $('watermarkEnabled').checked,
    watermarkOpacity: $('watermarkOpacity').value,
    logoDataUrl,
    watermarkDataUrl,
    indexRows,
  };
}

function applyFormData(data) {
  if (!data) return;
  setTemplate(data.template || 'classic');
  styleState = { ...DEFAULT_STYLE, ...(data.style || {}) };
  applyStyleState();
  $('institutionName').value = data.institutionName ?? 'Mymensingh Engineering College';
  $('department').value = data.department ?? $('department').value;
  $('documentType').value = data.documentType ?? $('documentType').value;
  $('courseCode').value = data.courseCode ?? '';
  $('courseName').value = data.courseName ?? '';
  $('serialNo').value = data.serialNo ?? '';
  $('submissionDate').value = data.submissionDate ?? '';
  $('reportTitle').value = data.reportTitle ?? '';
  $('studentName').value = data.studentName ?? '';
  $('studentRoll').value = data.studentRoll ?? '';
  $('studentReg').value = data.studentReg ?? '';
  $('studentExamRoll').value = data.studentExamRoll ?? '';
  $('studentBatch').value = data.studentBatch ?? '';

  $('manualTeacherEntry').checked = !!data.manualTeacherEntry;
  $('teacherNameManual').value = data.teacherNameManual ?? '';
  $('teacherDesigManual').value = data.teacherDesigManual ?? '';
  $('teacherDeptManual').value = data.teacherDeptManual ?? '';
  $('teacherManualWrap').hidden = !data.manualTeacherEntry;

  selectedTeacher = data.selectedTeacher ?? null;
  if (selectedTeacher && !data.manualTeacherEntry) {
    $('teacherSearchWrap').hidden = true;
    $('teacherChosen').hidden = false;
    $('tcName').textContent = selectedTeacher.name;
    $('tcDesig').textContent = selectedTeacher.designation;
    $('tcDept').textContent = selectedTeacher.department;
  } else {
    $('teacherSearchWrap').hidden = !!data.manualTeacherEntry;
    $('teacherChosen').hidden = true;
  }

  $('watermarkEnabled').checked = data.watermarkEnabled ?? true;
  $('watermarkOpacity').value = data.watermarkOpacity ?? 20;
  $('opacityValue').textContent = `${$('watermarkOpacity').value}%`;

  logoDataUrl = data.logoDataUrl ?? null;
  watermarkDataUrl = data.watermarkDataUrl ?? null;
  $('logoPreviewImg').src = logoDataUrl || '';
  $('logoPreviewImg').hidden = !logoDataUrl;
  $('logoUploadHint').hidden = !!logoDataUrl;
  $('logoRemoveBtn').hidden = !logoDataUrl || logoDataUrl === DEFAULT_LOGO;
  $('watermarkPreviewImg').src = watermarkDataUrl || '';
  $('watermarkPreviewImg').hidden = !watermarkDataUrl;
  $('watermarkUploadHint').hidden = !!watermarkDataUrl;
  $('watermarkRemoveBtn').hidden = !watermarkDataUrl || watermarkDataUrl === DEFAULT_LOGO;

  indexRows = Array.isArray(data.indexRows) ? data.indexRows : [];
  renderIndexTable();

  updatePreview();
}

/* =========================================================
   AUTOSAVE (silent, every change) vs. explicit SAVE (named slot)
========================================================= */
function autosave() {
  try { localStorage.setItem('coverAutosave', JSON.stringify(collectFormData())); }
  catch (e) { /* storage might be full — ignore silently for autosave */ }
}
function restoreAutosave() {
  try {
    const raw = localStorage.getItem('coverAutosave');
    if (raw) applyFormData(JSON.parse(raw));
  } catch (e) { /* ignore corrupt data */ }
}

/* =========================================================
   ACTION BUTTONS
========================================================= */
function wireActionButtons() {
  $('btnPrint').addEventListener('click', () => {
    validateRequired();
    printElement($('coverPage'));
  });

  $('btnPdf').addEventListener('click', downloadPdf);

  $('btnSave').addEventListener('click', () => {
    validateRequired();
    saveToHistory();
    setStatus('Saved to recent history.');
  });

  $('btnLoad').addEventListener('click', () => {
    openHistory();
    setStatus('Pick a saved cover from the history panel.');
  });

  $('btnDuplicate').addEventListener('click', () => {
    saveToHistory(true);
    setStatus('Duplicated — a copy was added to history.');
  });

  $('btnReset').addEventListener('click', () => {
    if (!confirm('Reset the form? Unsaved changes will be lost.')) return;
    localStorage.removeItem('coverAutosave');
    location.reload();
  });
}

function validateRequired() {
  const requiredIds = ['institutionName','courseCode','courseName','studentName'];
  let ok = true;
  requiredIds.forEach(id => {
    const el = $(id);
    validateField(el);
    if (el.classList.contains('invalid')) ok = false;
  });
  if (!ok) setStatus('Heads up: some recommended fields are still empty.', true);
  return ok;
}

function setStatus(msg, isError) {
  const el = $('statusLine');
  el.textContent = msg;
  el.style.color = isError ? 'var(--danger)' : 'var(--primary)';
  clearTimeout(setStatus._t);
  setStatus._t = setTimeout(() => { el.textContent = ''; }, 3500);
}

/* =========================================================
   PRINT & PDF (shared by the Cover Page and the Index Page)
========================================================= */

/* Clones a printable sheet and strips out anything that only makes sense on
   screen: drag handles, delete buttons (anything marked .no-print), and live
   <input> elements — which are swapped for plain <span> text so the exported
   page shows crisp glyphs instead of form-field chrome. */
function preparePrintable(sourceEl) {
  const clone = sourceEl.cloneNode(true);
  clone.removeAttribute('id');
  clone.querySelectorAll('.no-print').forEach((el) => el.remove());
  clone.querySelectorAll('input').forEach((input) => {
    const span = document.createElement('span');
    span.className = input.className.replace(/\bidx-input\b/, 'idx-static');
    span.textContent = input.value.trim() || '—';
    input.replaceWith(span);
  });
  return clone;
}

/* Prints ONLY the given sheet (cover or index), perfectly aligned to A4.
   The clone is dropped into #printRoot — a direct child of <body>, outside the
   zoomable/scrollable preview wrappers — so the on-screen zoom level (or any
   ancestor transform) can never distort what actually reaches the printer. */
function printElement(sourceEl) {
  const root = $('printRoot');
  root.innerHTML = '';
  root.appendChild(preparePrintable(sourceEl));
  // give the browser a frame to lay the clone out before opening print preview
  requestAnimationFrame(() => window.print());
}
window.addEventListener('afterprint', () => { $('printRoot').innerHTML = ''; });

/* Exports the given sheet as a PDF. singlePage=true (cover) trims the output
   down to exactly one A4 page; singlePage=false (index) lets a long table
   flow naturally across as many pages as it needs. */
function exportPdf(sourceEl, filename, { singlePage = true } = {}) {
  const clone = preparePrintable(sourceEl);
  clone.style.margin = '0';
  clone.style.boxShadow = 'none';
  clone.style.border = 'none';

  // render off-screen, at natural (unzoomed) scale, so PDF output never
  // inherits the live preview's zoom transform
  const holder = document.createElement('div');
  holder.style.cssText = 'position:fixed; left:-10000px; top:0; pointer-events:none;';
  holder.appendChild(clone);
  document.body.appendChild(holder);

  if (typeof html2pdf === 'undefined') {
    holder.remove();
    return Promise.reject(new Error('html2pdf library failed to load'));
  }

  const opt = {
    margin: 0,
    filename,
    image: { type: 'jpeg', quality: 0.98 },
    html2canvas: { scale: 3, useCORS: true, scrollX: 0, scrollY: 0, windowWidth: clone.scrollWidth, windowHeight: clone.scrollHeight },
    jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
    pagebreak: singlePage ? { mode: ['avoid-all'] } : { mode: ['css', 'legacy'] }
  };

  return html2pdf().set(opt).from(clone).toPdf().get('pdf')
    .then((pdf) => {
      if (singlePage) {
        const totalPages = pdf.internal.getNumberOfPages();
        for (let i = totalPages; i > 1; i--) pdf.deletePage(i);
      }
      return pdf;
    })
    .save()
    .finally(() => holder.remove());
}

function downloadPdf() {
  validateRequired();
  const studentName = $('studentName').value.trim().replace(/\s+/g, '_') || 'cover';
  const docType = $('documentType').value.replace(/\s+/g, '_');
  setStatus('Preparing PDF…');
  exportPdf($('coverPage'), `${docType}_Cover_${studentName}.pdf`, { singlePage: true })
    .then(() => setStatus('PDF downloaded.'))
    .catch(() => setStatus('Could not generate PDF.', true));
}

/* =========================================================
   HISTORY (last 20 covers)
========================================================= */
function getHistory() {
  try { return JSON.parse(localStorage.getItem('coverHistory') || '[]'); }
  catch (e) { return []; }
}
function setHistory(arr) {
  localStorage.setItem('coverHistory', JSON.stringify(arr.slice(0, 20)));
}

function saveToHistory() {
  const data = collectFormData();
  const entry = {
    id: Date.now(),
    label: data.reportTitle || `${data.documentType} — ${data.courseCode || 'Untitled'}`,
    sub: `${data.studentName || 'Unnamed'} · ${data.documentType}`,
    data
  };
  const hist = getHistory();
  hist.unshift(entry);
  setHistory(hist);
  renderHistory();
}

function renderHistory() {
  const hist = getHistory();
  const list = $('historyList');
  const empty = $('historyEmpty');
  list.innerHTML = '';
  empty.hidden = hist.length > 0;

  hist.forEach(entry => {
    const li = document.createElement('li');
    li.className = 'history-item';
    li.innerHTML = `<strong>${escapeHtml(entry.label)}</strong><span>${escapeHtml(entry.sub)}</span>`;
    li.addEventListener('click', () => {
      applyFormData(entry.data);
      closeHistory();
      setStatus('Loaded from history.');
    });
    list.appendChild(li);
  });
}

function wireHistoryDrawer() {
  $('historyToggle').addEventListener('click', openHistory);
  $('closeHistory').addEventListener('click', closeHistory);
  $('scrim').addEventListener('click', closeHistory);
}
function openHistory() { $('historyDrawer').classList.add('open'); $('scrim').classList.add('show'); }
function closeHistory() { $('historyDrawer').classList.remove('open'); $('scrim').classList.remove('show'); }

/* =========================================================
   THEME TOGGLE
========================================================= */
function applyStoredTheme() {
  const saved = localStorage.getItem('coverTheme') || 'light';
  document.documentElement.setAttribute('data-theme', saved);
  $('themeToggle').addEventListener('click', () => {
    const current = document.documentElement.getAttribute('data-theme');
    const next = current === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('coverTheme', next);
  });
}

/* =========================================================
   ZOOM (reused for both the Cover Page and Index Page previews)
========================================================= */
function createZoomController(wrapEl, zoomInBtn, zoomOutBtn, labelEl) {
  let zoom = 1;
  const apply = () => { wrapEl.style.transform = `scale(${zoom})`; labelEl.textContent = `${Math.round(zoom * 100)}%`; };
  zoomInBtn.addEventListener('click', () => { zoom = Math.min(1.4, zoom + 0.1); apply(); });
  zoomOutBtn.addEventListener('click', () => { zoom = Math.max(0.4, zoom - 0.1); apply(); });
  apply();
}

/* =========================================================
   VIEW TABS — Cover Page / Index Page switcher
========================================================= */
function wireViewTabs() {
  document.querySelectorAll('.view-tab').forEach((btn) => {
    btn.addEventListener('click', () => switchView(btn.dataset.view));
  });
}

function switchView(view) {
  document.querySelectorAll('.view-tab').forEach((btn) => {
    btn.classList.toggle('active', btn.dataset.view === view);
  });
  $('viewCover').hidden = view !== 'cover';
  $('viewIndex').hidden = view !== 'index';
  if (view === 'index') updateIndexHeader();
}

/* =========================================================
   INDEX PAGE GENERATOR
   A lightweight, editable table (Serial No. / Experiment Name / Page Number)
   that lives directly on the printable A4 sheet. Rows can be added, deleted,
   edited in place, and dragged into a new order; page numbers are always
   typed in by hand (never auto-generated), per spec.
========================================================= */

function makeRowId() {
  return 'r' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function addIndexRow(prefill) {
  indexRows.push({ id: makeRowId(), name: (prefill && prefill.name) || '', page: (prefill && prefill.page) || '' });
  renderIndexTable();
  requestAnimationFrame(() => {
    const inputs = document.querySelectorAll('#idxTableBody .idx-name-input');
    if (inputs.length) inputs[inputs.length - 1].focus();
  });
}

function escapeAttr(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/* Rebuilds the whole table body from `indexRows`. Called after any add /
   delete / reorder so the Serial No. column always reflects display order. */
function renderIndexTable() {
  const body = $('idxTableBody');
  body.innerHTML = '';
  indexRows.forEach((row, i) => {
    const tr = document.createElement('tr');
    tr.className = 'idx-row';
    tr.draggable = true;
    tr.dataset.id = row.id;
    tr.innerHTML = `
      <td class="idx-drag no-print" title="Drag to reorder">⠿</td>
      <td class="idx-serial">${String(i + 1).padStart(2, '0')}</td>
      <td class="idx-name"><input type="text" class="idx-input idx-name-input" placeholder="e.g. Linked List" value="${escapeAttr(row.name)}"></td>
      <td class="idx-page"><input type="text" class="idx-input idx-page-input" placeholder="Page" value="${escapeAttr(row.page)}"></td>
      <td class="idx-actions no-print"><button type="button" class="idx-del" data-id="${row.id}" title="Delete row">✕</button></td>
    `;
    body.appendChild(tr);
  });
  $('idxEmptyMsg').hidden = indexRows.length > 0;
  wireIndexRowEvents();
  autosave();
}

function wireIndexRowEvents() {
  const body = $('idxTableBody');

  body.querySelectorAll('.idx-name-input').forEach((inp) => {
    inp.addEventListener('input', () => {
      const row = indexRows.find((r) => r.id === inp.closest('tr').dataset.id);
      if (row) { row.name = inp.value; autosave(); }
    });
  });
  body.querySelectorAll('.idx-page-input').forEach((inp) => {
    inp.addEventListener('input', () => {
      const row = indexRows.find((r) => r.id === inp.closest('tr').dataset.id);
      if (row) { row.page = inp.value; autosave(); }
    });
  });
  body.querySelectorAll('.idx-del').forEach((btn) => {
    btn.addEventListener('click', () => {
      indexRows = indexRows.filter((r) => r.id !== btn.dataset.id);
      renderIndexTable();
    });
  });

  wireIndexDragAndDrop(body);
}

/* Native HTML5 drag & drop reordering. Rows are moved live in the DOM as you
   drag past them; on drop, `indexRows` is re-sorted to match and the table is
   re-rendered once so the Serial No. numbers refresh cleanly. */
function wireIndexDragAndDrop(body) {
  body.querySelectorAll('tr.idx-row').forEach((tr) => {
    tr.addEventListener('dragstart', () => tr.classList.add('dragging'));
    tr.addEventListener('dragend', () => tr.classList.remove('dragging'));
    tr.addEventListener('dragover', (e) => {
      e.preventDefault();
      const dragging = body.querySelector('.dragging');
      if (!dragging || dragging === tr) return;
      const rect = tr.getBoundingClientRect();
      const before = (e.clientY - rect.top) < rect.height / 2;
      body.insertBefore(dragging, before ? tr : tr.nextSibling);
    });
    tr.addEventListener('drop', (e) => {
      e.preventDefault();
      const newOrder = [...body.querySelectorAll('tr.idx-row')].map((r) => r.dataset.id);
      indexRows.sort((a, b) => newOrder.indexOf(a.id) - newOrder.indexOf(b.id));
      renderIndexTable();
    });
  });
}

/* Keeps the Index Page's header (institution / logo / department / doctype)
   in lockstep with the Cover Page form, so both sheets of the same report
   always show the same identity — no separate fields to fill in twice. */
function updateIndexHeader() {
  const institution = $('institutionName').value.trim() || 'Your Institution Name';
  $('pIdxInstitution').textContent = institution;
  $('pIdxDepartment').textContent = `Department of ${$('department').value}`;
  $('pIdxDocType').textContent = $('documentType').value.toUpperCase();

  const logoImg = $('pIdxLogo');
  if (logoDataUrl) { logoImg.src = logoDataUrl; logoImg.hidden = false; }
  else { logoImg.hidden = true; }
}

function wireIndexActions() {
  $('idxAddRow').addEventListener('click', () => addIndexRow());

  $('idxClearAll').addEventListener('click', () => {
    if (!indexRows.length) return;
    if (!confirm('Clear all index rows? This cannot be undone.')) return;
    indexRows = [];
    renderIndexTable();
    setIndexStatus('Cleared all rows.');
  });

  $('idxPrint').addEventListener('click', () => printElement($('indexPage')));

  $('idxDownloadPdf').addEventListener('click', () => {
    setIndexStatus('Preparing PDF…');
    const docType = $('documentType').value.replace(/\s+/g, '_');
    exportPdf($('indexPage'), `${docType}_Index.pdf`, { singlePage: false })
      .then(() => setIndexStatus('PDF downloaded.'))
      .catch(() => setIndexStatus('Could not generate PDF.', true));
  });
}

function setIndexStatus(msg, isError) {
  const el = $('idxStatusLine');
  el.textContent = msg;
  el.style.color = isError ? 'var(--danger)' : 'var(--primary)';
  clearTimeout(setIndexStatus._t);
  setIndexStatus._t = setTimeout(() => { el.textContent = ''; }, 3500);
}
